const email = $input.first().json;

const snippet = email.snippet || '';
const from = email.From || '';

// Use regex to extract values from snippet
const nameMatch = snippet.match(/Name:\s*(.+?)\s*Email:/i);
const emailMatch = snippet.match(/Email:\s*(\S+)/i);
const phoneMatch = snippet.match(/Phone:\s*(\d{10,})/i);
const roleMatch = snippet.match(/Role:\s*(.+?)\s*Total Experience:/i);
const experienceMatch = snippet.match(/Total Experience:\s*(\d+)/i);
const recruiterMatch = snippet.match(/Recruiter:\s*(.+?)\s*Resume/i);
const resumeUrlMatch = snippet.match(/Resume URL:\s*(.+?)(?:\s|$)/i);

// Extract sender email from From field
const fromEmailMatch = from.match(/<(.+?)>/);
const sourceEmail = fromEmailMatch ? fromEmailMatch[1] : from;

return [
  {
    json: {
      candidate_name: nameMatch?.[1]?.trim() || '',
      candidate_email: emailMatch?.[1]?.trim() || '',
      candidate_phone: phoneMatch?.[1]?.trim() || '',
      role_applied: roleMatch?.[1]?.trim() || '',
      years_of_experience: experienceMatch?.[1]?.trim() || '',
      recruiter: recruiterMatch?.[1]?.trim() || '',
      resume_url: resumeUrlMatch?.[1]?.trim() || '',
      source_email: sourceEmail
    }
  }
];

const candidate =  $("Code").all()[0].json;
const sheetRows = $('Google Sheets1').all();

const emailToCheck = candidate.candidate_email?.toLowerCase().trim();

// Check if candidate_email already exists
const isDuplicate = sheetRows.some(row => {
  return row.json.candidate_email?.toLowerCase().trim() === emailToCheck;
});

return [
  {
    json: {
      ...candidate,
      isDuplicate
    }
  }
];
